import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  CircleGeometry,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  AmbientLight,
  DirectionalLight,
  PointLight,
  Box3,
  Vector3
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

function hexRgb(hex) {
  const value = hex.replace('#', '');
  return [
    parseInt(value.slice(0, 2), 16) / 255,
    parseInt(value.slice(2, 4), 16) / 255,
    parseInt(value.slice(4, 6), 16) / 255
  ];
}

function gradientMaterial(topColor, bottomColor) {
  const material = new MeshBasicNodeMaterial();
  const top = hexRgb(topColor);
  const bottom = hexRgb(bottomColor);
  const gradient = smoothstep(0.05, 0.95, uv().y);
  material.colorNode = mix(
    vec3(bottom[0], bottom[1], bottom[2]),
    vec3(top[0], top[1], top[2]),
    gradient
  );
  return material;
}

function createNode(config, ctx) {
  const {
    Group: ThreeGroup,
    Mesh: ThreeMesh
  } = ctx.THREE;

  const root = new ThreeGroup();
  root.name = 'nova-atelier-thumbnail-card';
  root.userData.handlers = {};

  const ownedResources = [];
  const animationHandles = [];
  const primitiveResults = [];

  const card = new ThreeGroup();
  card.name = 'thumbnail-card-assembly';
  root.add(card);

  const surfaceMaterial = new MeshStandardNodeMaterial({
    color: '#16161d',
    roughness: 0.72,
    metalness: 0.28
  });
  const paperMaterial = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    roughness: 0.64,
    metalness: 0.08
  });
  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.9
  });
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });

  ownedResources.push(surfaceMaterial, paperMaterial, accentMaterial, shadowMaterial);

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = gradientMaterial('#16161d', '#0b0b10');
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'designed-dark-gradient-stage';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  ownedResources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new CircleGeometry(1.45, 48);
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.name = 'radial-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.25, 0.58, 1);
  contactShadow.position.set(0, -1.04, -0.08);
  card.add(contactShadow);
  ownedResources.push(shadowGeometry);

  const panelGeometry = new BoxGeometry(3.25, 2.35, 0.18);
  const panel = new Mesh(panelGeometry, surfaceMaterial);
  panel.name = 'thumbnail-card-panel';
  panel.position.set(0, 0, 0);
  card.add(panel);
  ownedResources.push(panelGeometry);

  const innerGeometry = new BoxGeometry(2.96, 1.78, 0.035);
  const innerPanel = new Mesh(innerGeometry, paperMaterial);
  innerPanel.name = 'thumbnail-image-field';
  innerPanel.position.set(0, 0.18, 0.12);
  card.add(innerPanel);
  ownedResources.push(innerGeometry);

  const captionGeometry = new BoxGeometry(2.96, 0.42, 0.05);
  const captionStrip = new Mesh(captionGeometry, surfaceMaterial);
  captionStrip.name = 'caption-strip';
  captionStrip.position.set(0, -0.86, 0.14);
  card.add(captionStrip);
  ownedResources.push(captionGeometry);

  const edgeGeometry = new BoxGeometry(0.045, 2.18, 0.045);
  const leftEdge = new Mesh(edgeGeometry, accentMaterial);
  const rightEdge = new Mesh(edgeGeometry, accentMaterial);
  leftEdge.name = 'accent-focus-edge-left';
  rightEdge.name = 'accent-focus-edge-right';
  leftEdge.position.set(-1.57, 0.02, 0.2);
  rightEdge.position.set(1.57, 0.02, 0.2);
  leftEdge.scale.y = 0.16;
  rightEdge.scale.y = 0.16;
  leftEdge.visible = false;
  rightEdge.visible = false;
  card.add(leftEdge, rightEdge);
  ownedResources.push(edgeGeometry);

  const key = new DirectionalLight('#e8ecf2', 1.1);
  key.position.set(3.2, 4.2, 5.5);
  card.add(key);

  const rim = new PointLight('#ff2a38', 0.72, 5.5, 2);
  rim.position.set(-2.2, 1.4, 2.8);
  card.add(rim);

  const fill = new AmbientLight('#e8ecf2', 0.6);
  card.add(fill);

  const meshHolder = new ThreeGroup();
  meshHolder.name = 'machined-gear-subject';
  meshHolder.position.set(0, 0.12, 0.34);
  card.add(meshHolder);

  const loadPromise = config.meshUrl
    ? ctx.glbLoader.loadGLB(config.meshUrl)
        .then((gltf) => {
          if (!gltf || !gltf.scene) return;

          const subject = gltf.scene;
          subject.name = 'gear-a-loaded-mesh';

          const bounds = new Box3().setFromObject(subject);
          const size = bounds.getSize(new Vector3());
          const maxDimension = Math.max(size.x, size.y, size.z) || 1;
          const fitScale = 1.72 / maxDimension;
          subject.scale.multiplyScalar(fitScale);

          const fittedBounds = new Box3().setFromObject(subject);
          const center = fittedBounds.getCenter(new Vector3());
          subject.position.sub(center);

          subject.traverse((child) => {
            child.castShadow = true;
            child.receiveShadow = true;
          });

          meshHolder.add(subject);
        })
        .catch(() => {});

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || !item.text) continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.09,
      color: item.role === 'caption' ? '#e8ecf2' : '#16161d',
      align: 'center',
      letterSpacingPx: item.role === 'label' ? 5 : 0
    });
    textObject.position.set(0, -0.86, 0.19);
    textObject.scale.setScalar(0.012);
    card.add(textObject);
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (!primitive || !primitive.name || !ctx.primitives?.[primitive.name]) continue;
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  const baseY = card.position.y;
  const baseZ = card.position.z;

  root.userData.handlers.hover = (isHovered = true) => {
    const targetY = isHovered ? baseY + 0.15 : baseY;
    const targetZ = isHovered ? baseZ + 0.025 : baseZ;
    const tween = gsap.to(card.position, {
      y: targetY,
      z: targetZ,
      duration: 0.45,
      ease: 'power3.out'
    });
    animationHandles.push(tween);
  };

  root.userData.handlers.click = () => {
    const press = gsap.timeline();
    press
      .to(card.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(card.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.42,
        ease: 'back.out(2.2)'
      });
    animationHandles.push(press);
    ctx.emit('hub-home.select', { node: root });
  };

  root.userData.handlers.focus = () => {
    leftEdge.visible = true;
    rightEdge.visible = true;
    const tween = gsap.to([leftEdge.scale, rightEdge.scale], {
      y: 1,
      duration: 0.3,
      ease: 'power2.out'
    });
    animationHandles.push(tween);
  };

  root.userData.handlers.blur = () => {
    const tween = gsap.to([leftEdge.scale, rightEdge.scale], {
      y: 0.16,
      duration: 0.3,
      ease: 'power2.out',
      onComplete: () => {
        leftEdge.visible = false;
        rightEdge.visible = false;
      }
    });
    animationHandles.push(tween);
  };

  root.userData.cleanup = () => {
    for (const handle of animationHandles) {
      if (handle && typeof handle.kill === 'function') handle.kill();
    }

    for (const result of primitiveResults) {
      if (result && typeof result.cleanup === 'function') result.cleanup();
      if (result?.timeline && typeof result.timeline.kill === 'function') {
        result.timeline.kill();
      }
    }

    root.traverse((object) => {
      if (object.geometry && ownedResources.includes(object.geometry)) {
        object.geometry.dispose();
      }
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) {
          if (ownedResources.includes(material) && typeof material.dispose === 'function') {
            material.dispose();
          }
        }
      }
    });

    for (const resource of ownedResources) {
      if (resource && typeof resource.dispose === 'function') resource.dispose();
    }
  };

  void loadPromise;
  return root;
}

export default createNode;
